insert into public.candidates (id, campaign_id, party_id, portrait_asset_id, slug, full_name, short_name, short_bio, positioning, accent_key, display_order, tie_break_order, publication_status, published_at) values
  ('brun', 'ps-2026', 'parti-socialiste', 'brun-portrait', 'philippe-brun', 'Philippe Brun', 'Brun', 'Il place la réindustrialisation, le pouvoir d’achat et la maîtrise publique de l’énergie au cœur de sa démarche.', 'Réindustrialisation, salaires et partage de l’effort fiscal.', 'coral', 1, 3, 'published', '2026-09-03T00:00:00+02:00'),
  ('faure', 'ps-2026', 'parti-socialiste', 'faure-portrait', 'olivier-faure', 'Olivier Faure', 'Faure', 'Il défend une ligne sociale, écologique et européenne, avec un accent fort sur l’école et les services publics.', 'École, services publics et justice fiscale au premier plan.', 'yellow', 2, 2, 'published', '2026-09-03T00:00:00+02:00'),
  ('glucksmann', 'ps-2026', 'place-publique', 'glucksmann-portrait', 'raphael-glucksmann', 'Raphaël Glucksmann', 'Glucksmann', 'Il articule son projet autour d’une transformation écologique rapide, d’une Europe plus forte et d’une meilleure rémunération du travail.', 'Europe, transformation écologique et souveraineté démocratique.', 'sky', 3, 4, 'published', '2026-09-03T00:00:00+02:00'),
  ('guedj', 'ps-2026', 'parti-socialiste', 'guedj-portrait', 'jerome-guedj', 'Jérôme Guedj', 'Guedj', 'Il construit sa démarche autour de la « République du soin », du travail, de l’éducation et de l’intégration.', 'Soin, services publics, laïcité et intégration républicaine.', 'pink', 4, 1, 'published', '2026-09-03T00:00:00+02:00'),
  ('royal', 'ps-2026', 'parti-socialiste', 'royal-portrait', 'segolene-royal', 'Ségolène Royal', 'Royal', 'Elle met en avant la protection du pouvoir d’achat, l’héritage de la COP21 et un rôle diplomatique renforcé pour la France.', 'Pouvoir d’achat, écologie et souveraineté énergétique.', 'purple', 5, 5, 'published', '2026-09-03T00:00:00+02:00');
