  ('2026-09-03-v1', 'travail-retraites', 'Q03', 'Faut-il revenir sur la retraite à 64 ans et permettre un départ à 62 ans ou moins ?', null, 3, true, 'published', '2026-09-03', '2026-09-03T00:00:00+02:00'),
