  ((select id from public.questions where quiz_version_id = '2026-09-03-v1' and code = 'Q01'), 'faure', 2, 'documented', 'Il défend un ISF climatique et une contribution accrue des patrimoines et revenus du capital.', '2025-04-07', 'high', 'official-program', 'published', '2026-09-03', '2026-09-03T00:00:00+02:00'),
  ((select id from public.questions where quiz_version_id = '2026-09-03-v1' and code = 'Q01'), 'glucksmann', 2, 'documented', 'Il défend une taxation accrue des plus hauts patrimoines et des très grosses successions.', '2026-08-26', 'high', 'interview', 'published', '2026-09-03', '2026-09-03T00:00:00+02:00'),
  ((select id from public.questions where quiz_version_id = '2026-09-03-v1' and code = 'Q01'), 'guedj', 2, 'documented', 'Il affirme que les grandes fortunes et les patrimoines les plus élevés doivent contribuer davantage.', '2026-09-03', 'high', 'official-program', 'published', '2026-09-03', '2026-09-03T00:00:00+02:00'),
  ((select id from public.questions where quiz_version_id = '2026-09-03-v1' and code = 'Q01'), 'royal', 2, 'documented', 'Elle exige que le rétablissement de l’ISF financier soit remis au cœur du débat fiscal.', '2026-08-31', 'high', 'interview', 'published', '2026-09-03', '2026-09-03T00:00:00+02:00'),
  ((select id from public.questions where quiz_version_id = '2026-09-03-v1' and code = 'Q02'), 'brun', 2, 'documented', 'Il défend un protectionnisme européen et le blocage des produits qui ne respectent pas nos normes.', '2026-08-19', 'high', 'official-program', 'published', '2026-09-03', '2026-09-03T00:00:00+02:00'),
