  ((select id from public.questions where quiz_version_id = '2026-09-03-v1' and code = 'Q02'), 'guedj', 2, 'documented', 'Il défend un patriotisme économique contre la concurrence sociale et environnementale déloyale.', '2026-09-03', 'high', 'official-program', 'published', '2026-09-03', '2026-09-03T00:00:00+02:00'),
