  ((select id from public.questions where quiz_version_id = '2026-09-03-v1' and code = 'Q03'), 'faure', 2, 'documented', 'Il propose de ramener l’âge légal à 62 ans et a voté l’abrogation de la réforme.', '2025-06-05', 'high', 'parliamentary-vote', 'published', '2026-09-03', '2026-09-03T00:00:00+02:00'),
  ((select id from public.questions where quiz_version_id = '2026-09-03-v1' and code = 'Q03'), 'glucksmann', 0, 'documented', 'Il veut abroger la réforme de 2023 mais remplacer l’âge uniforme par un système différencié.', '2026-08-26', 'high', 'interview', 'published', '2026-09-03', '2026-09-03T00:00:00+02:00'),
