insert into public.candidate_highlights (id, candidate_id, theme_id, title, summary, metric_text, editorial_status, display_order, publication_status, published_at) values
  ('brun-h1', 'brun', 'travail-retraites', 'Le « salaire Brun »', 'Rendre la CSG progressive pour augmenter le salaire net, surtout pour les revenus modestes et moyens.', null, 'documented-public-position', 1, 'published', '2026-09-03T00:00:00+02:00'),
  ('brun-h2', 'brun', 'economie-fiscalite', 'Taxer le capital pour alléger le travail', 'Financer une baisse de CSG par une contribution accrue des revenus du capital.', null, 'documented-public-position', 2, 'published', '2026-09-03T00:00:00+02:00'),
  ('brun-h3', 'brun', 'economie-fiscalite', 'Rétablir un ISF', 'Rétablir un impôt sur les grandes fortunes, en particulier sur les actifs non professionnels.', null, 'documented-public-position', 3, 'published', '2026-09-03T00:00:00+02:00'),
  ('brun-h4', 'brun', 'economie-fiscalite', 'Supprimer la flat tax', 'Réintégrer les revenus du capital dans un système d’imposition plus progressif.', null, 'documented-public-position', 4, 'published', '2026-09-03T00:00:00+02:00'),
  ('brun-h5', 'brun', 'economie-fiscalite', 'Cinq usines par département', 'Fixer un objectif de cinq nouvelles usines par département au cours du quinquennat.', '5', 'documented-public-position', 5, 'published', '2026-09-03T00:00:00+02:00'),
  ('brun-h6', 'brun', 'ecologie-energie', 'Un monopole public d’EDF', 'Revenir à un monopole public pour produire une électricité décarbonée moins chère.', null, 'documented-public-position', 6, 'published', '2026-09-03T00:00:00+02:00'),
  ('brun-h7', 'brun', 'economie-fiscalite', 'Une compagnie minière nationale', 'Créer une entreprise publique française pour sécuriser l’accès aux minerais stratégiques.', null, 'documented-public-position', 7, 'published', '2026-09-03T00:00:00+02:00'),
  ('brun-h8', 'brun', 'travail-retraites', 'Une capitalisation collective des retraites', 'Ajouter une part de capitalisation pilotée collectivement avec les organisations syndicales.', null, 'documented-public-position', 8, 'published', '2026-09-03T00:00:00+02:00'),
  ('faure-h1', 'faure', 'education', '19 élèves par classe', 'Profiter de la baisse démographique pour réduire les effectifs plutôt que fermer des classes.', '19', 'documented-public-position', 1, 'published', '2026-09-03T00:00:00+02:00'),
  ('faure-h2', 'faure', 'education', 'Petit-déjeuner gratuit à l’école', 'Proposer gratuitement un petit-déjeuner aux élèves qui en ont besoin.', null, 'documented-public-position', 2, 'published', '2026-09-03T00:00:00+02:00'),
  ('faure-h3', 'faure', 'education', 'Plus de santé scolaire', 'Augmenter fortement le nombre de médecins, infirmiers et psychologues scolaires.', null, 'documented-public-position', 3, 'published', '2026-09-03T00:00:00+02:00'),
  ('faure-h4', 'faure', 'education', 'Renforcer les AESH', 'Accroître les moyens consacrés à l’accompagnement des élèves en situation de handicap.', null, 'documented-public-position', 4, 'published', '2026-09-03T00:00:00+02:00'),
  ('faure-h5', 'faure', 'travail-retraites', 'Dégeler le point d’indice', 'Revaloriser les agents publics, dont les enseignants, en dégelant d’abord le point d’indice.', null, 'documented-public-position', 5, 'published', '2026-09-03T00:00:00+02:00'),
  ('faure-h6', 'faure', 'travail-retraites', 'Revenir à la retraite à 62 ans', 'Annuler le recul de l’âge légal à 64 ans et restaurer un départ à 62 ans.', '62', 'documented-public-position', 6, 'published', '2026-09-03T00:00:00+02:00'),
  ('faure-h7', 'faure', 'economie-fiscalite', 'Taxer davantage les très grandes fortunes', 'Renforcer la progressivité de l’impôt sur les patrimoines et héritages les plus élevés.', null, 'documented-public-position', 7, 'published', '2026-09-03T00:00:00+02:00'),
  ('faure-h8', 'faure', 'sante', 'Un fonds pour l’alimentation', 'Permettre aux ménages modestes d’acheter une alimentation suffisante et de qualité à prix réduit.', null, 'documented-public-position', 8, 'published', '2026-09-03T00:00:00+02:00'),
  ('glucksmann-h1', 'glucksmann', 'ecologie-energie', '100 jours de transformation écologique', 'Ouvrir le quinquennat par cent jours consacrés à la transformation écologique.', '100', 'documented-public-position', 1, 'published', '2026-09-03T00:00:00+02:00'),
  ('glucksmann-h2', 'glucksmann', 'ecologie-energie', 'Sortir des énergies fossiles', 'Accélérer les renouvelables, l’électrification, la rénovation des bâtiments et les transports publics.', null, 'documented-public-position', 2, 'published', '2026-09-03T00:00:00+02:00'),
  ('glucksmann-h3', 'glucksmann', 'ecologie-energie', '50 milliards pour l’écologie', 'Investir environ 50 milliards d’euros sur cinq ans dans la transition écologique.', '50 Md€', 'documented-public-position', 3, 'published', '2026-09-03T00:00:00+02:00'),
  ('glucksmann-h4', 'glucksmann', 'economie-fiscalite', 'Taxer les méga-héritages', 'Taxer davantage le 1 % des héritages les plus élevés pour alléger les prélèvements sur le travail.', null, 'documented-public-position', 4, 'published', '2026-09-03T00:00:00+02:00'),
  ('glucksmann-h5', 'glucksmann', 'education', 'Augmenter les salaires enseignants', 'Revaloriser tous les enseignants de 10 %, avec jusqu’à 25 % à certains moments de carrière.', '+10 %', 'documented-public-position', 5, 'published', '2026-09-03T00:00:00+02:00'),
  ('glucksmann-h6', 'glucksmann', 'education', 'Des classes plus petites et plus mixtes', 'Réduire les effectifs et lier davantage les aides au privé à des objectifs de mixité sociale.', null, 'documented-public-position', 6, 'published', '2026-09-03T00:00:00+02:00'),
  ('glucksmann-h7', 'glucksmann', 'institutions', 'Un service civique de dix mois', 'Créer un service civique universel obligatoire, le service militaire restant optionnel.', '10 mois', 'documented-public-position', 7, 'published', '2026-09-03T00:00:00+02:00'),
  ('glucksmann-h8', 'glucksmann', 'international-defense', 'Une défense européenne plus forte', 'Soutenir l’Ukraine et construire des capacités communes de défense en Europe.', null, 'documented-public-position', 8, 'published', '2026-09-03T00:00:00+02:00'),
  ('guedj-h1', 'guedj', 'sante', 'La République du soin', 'Renforcer massivement l’hôpital public, l’accès aux soins et les services dans les territoires sous-dotés.', null, 'documented-public-position', 1, 'published', '2026-09-03T00:00:00+02:00'),
  ('guedj-h2', 'guedj', 'travail-retraites', 'Augmenter les bas salaires', 'Obtenir une hausse réelle de la rémunération des travailleurs les moins payés.', null, 'documented-public-position', 2, 'published', '2026-09-03T00:00:00+02:00'),
  ('guedj-h3', 'guedj', 'travail-retraites', 'Récompenser les entreprises qui augmentent', 'Mieux soutenir les entreprises qui revalorisent les salaires et partagent la valeur.', null, 'documented-public-position', 3, 'published', '2026-09-03T00:00:00+02:00'),
  ('guedj-h4', 'guedj', 'institutions', 'Un défenseur de la laïcité', 'Créer une autorité indépendante chargée de protéger et faire vivre la laïcité.', null, 'documented-public-position', 4, 'published', '2026-09-03T00:00:00+02:00'),
  ('guedj-h5', 'guedj', 'economie-fiscalite', 'Réindustrialiser les secteurs stratégiques', 'Investir dans les filières stratégiques et dans des technologies comme l’intelligence artificielle.', null, 'documented-public-position', 5, 'published', '2026-09-03T00:00:00+02:00'),
  ('guedj-h6', 'guedj', 'education', 'Priorité à l’éducation', 'Mieux former et payer les enseignants et réduire les classes dans les territoires en difficulté.', null, 'documented-public-position', 6, 'published', '2026-09-03T00:00:00+02:00'),
  ('guedj-h7', 'guedj', 'ecologie-energie', 'Une écologie du quotidien', 'Rénover les logements, améliorer les transports publics et développer une industrie verte.', null, 'documented-public-position', 7, 'published', '2026-09-03T00:00:00+02:00'),
  ('guedj-h8', 'guedj', 'immigration', 'Planifier immigration et intégration', 'Faire débattre le Parlement des besoins migratoires, créer une carte de séjour durable et renforcer l’intégration.', null, 'documented-public-position', 8, 'published', '2026-09-03T00:00:00+02:00'),
  ('royal-h1', 'royal', 'economie-fiscalite', 'Pouvoir d’achat et « ordre juste »', 'Lutter contre la vie chère tout en préservant la protection sociale.', null, 'current-campaign-priority', 1, 'published', '2026-09-03T00:00:00+02:00'),
  ('royal-h2', 'royal', 'ecologie-energie', 'Mettre en œuvre l’agenda de la COP21', 'Accélérer la transition écologique et l’action climatique.', null, 'current-campaign-priority', 2, 'published', '2026-09-03T00:00:00+02:00'),
  ('royal-h3', 'royal', 'ecologie-energie', 'Reconquérir l’autonomie énergétique', 'Protéger les PME, artisans, industriels et agriculteurs du coût de l’énergie.', null, 'current-campaign-priority', 3, 'published', '2026-09-03T00:00:00+02:00'),
  ('royal-h4', 'royal', 'ecologie-energie', 'Réduire la fiscalité de l’énergie', 'Diminuer les taxes qui contribuent au coût élevé de l’énergie.', null, 'current-campaign-priority', 4, 'published', '2026-09-03T00:00:00+02:00'),
  ('royal-h5', 'royal', 'securite-justice', 'Un État fort qui protège les enfants', 'Appliquer une tolérance zéro face aux violences, notamment sexuelles, faites aux enfants.', null, 'current-campaign-priority', 5, 'published', '2026-09-03T00:00:00+02:00'),
  ('royal-h6', 'royal', 'international-defense', 'Une France puissance de médiation', 'Redonner à la France un rôle diplomatique au service d’une paix négociée et durable.', null, 'current-campaign-priority', 6, 'published', '2026-09-03T00:00:00+02:00'),
  ('royal-h7', 'royal', 'travail-retraites', 'Revenir sur la retraite à 64 ans', 'Soutenir l’abrogation de la réforme des retraites adoptée en 2023.', null, 'documented-public-position', 7, 'published', '2026-09-03T00:00:00+02:00'),
  ('royal-h8', 'royal', 'economie-fiscalite', 'Faire davantage contribuer les grandes fortunes', 'Accroître la contribution fiscale des ménages les plus fortunés.', null, 'documented-public-position', 8, 'published', '2026-09-03T00:00:00+02:00');
